toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d23;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #2d3039;
}

::deep .sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #fff;
    border-bottom: 1px solid #2d3039;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
}

::deep .channel-item {
    padding: 10px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

::deep .channel-item:hover {
    background: #2d3039;
}

::deep .channel-item.active {
    background: #2d3039;
    border-left-color: #5865f2;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #fff;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #888;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #5865f2;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main area */
.main-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #23272e;
    color: #ddd;
    min-width: 0;
}

.main-area.with-thread {
    max-width: 55%;
}

::deep .message-header-bar {
    padding: 12px 20px;
    border-bottom: 1px solid #2d3039;
    background: #2b2f38;
}

::deep .message-header-bar h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-header-bar p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #888;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #666;
    font-size: 1.1rem;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #888;
    font-size: 0.8rem;
}

/* Message bubble */
::deep .message-bubble {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    position: relative;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #2d3039;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #fff;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #666;
}

::deep .message-content {
    margin-top: 4px;
    font-size: 0.9rem;
    line-height: 1.4;
    color: #ddd;
}

::deep .message-reactions {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2d3039;
    border: 1px solid #3d4049;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.1s;
}

::deep .reaction-badge:hover {
    background: #3d4049;
}

::deep .thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #5865f2;
    cursor: pointer;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 12px;
    display: flex;
    gap: 4px;
    background: #1a1d23;
    border: 1px solid #3d4049;
    border-radius: 6px;
    padding: 4px;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #ccc;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 4px;
    cursor: pointer;
}

::deep .action-btn:hover {
    background: #3d4049;
}

::deep .emoji-picker {
    position: absolute;
    top: -40px;
    right: 12px;
    background: #1a1d23;
    border: 1px solid #3d4049;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 4px;
}

::deep .emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #3d4049;
}

/* Message input */
::deep .message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #2d3039;
    background: #2b2f38;
}

::deep .message-textarea {
    flex: 1;
    resize: none;
    background: #1a1d23;
    border: 1px solid #3d4049;
    border-radius: 8px;
    padding: 10px 14px;
    color: #ddd;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

::deep .message-textarea:focus {
    border-color: #5865f2;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background 0.15s;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #1e2228;
    border-left: 1px solid #2d3039;
    display: flex;
    flex-direction: column;
    color: #ddd;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #2d3039;
}

::deep .thread-header h4 {
    margin: 0;
    color: #fff;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #888;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #3d4049;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #2d3039;
    background: #252930;
}

::deep .thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

::deep .thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #2d3039;
}

::deep .thread-reply:last-child {
    border-bottom: none;
}

